<|call:aws_s3api_put_lifecycle|> {"bucket": "genomics-scratch-prod", "rule": {"ID": "abort-stale-mpu", "Status": "Enabled", "Filter": {}, "AbortIncompleteMultipartUpload": {"DaysAfterInitiation": 7}}}
